class Moeda:
    def __init__(self, valor):
        self.valor = valor

    def __repr__(self):
        return f'Moeda({self.valor})'


class Nota(Moeda):
    def __str__(self):
        return f'nota de {self.valor}'


print(Moeda(1))
print(Nota(50))

def tentar(valor):
    try:
        n = int(valor)
    except ValueError:
        print("except")
        return "erro"
    else:
        print("else")
        return n
    finally:
        print("finally")


print(tentar("7"))
